input.command:
cd /voc/work/exercises/lesson-5-collaborate-with-ai-throughout-development/exercises/concept3-ai-test-creation/starter
T=$(mktemp -d); cp test_report_engine.py "$T/"
run_mutant () {
  name="$1"; body="$2"
  printf '%s\n' "$body" > "$T/report_engine.py"
  out=$(cd "$T" && python -m pytest test_report_engine.py -q --tb=no 2>&1 | tail -2 | head -1)
  echo "[$name] -> $out"
}
run_mutant "M1: swallow all exceptions" 'class ReportEngine:
    def __init__(self, loader):
        self.loader = loader
    def generate_report(self, filepath, mode):
        try:
            return mode.process_transactions(self.loader.load(filepath))
        except Exception:
            return {}'
run_mutant "M2: copy list before passing to mode" 'class ReportEngine:
    def __init__(self, loader):
        self.loader = loader
    def generate_report(self, filepath, mode):
        return mode.process_transactions(list(self.loader.load(filepath)))'
run_mutant "M3: skip mode, return raw transactions" 'class ReportEngine:
    def __init__(self, loader):
        self.loader = loader
    def generate_report(self, filepath, mode):
        return {"data": self.loader.load(filepath)}'
run_mutant "M4: truncate large inputs to 1000" 'class ReportEngine:
    def __init__(self, loader):
        self.loader = loader
    def generate_report(self, filepath, mode):
        return mode.process_transactions(self.loader.load(filepath)[:1000])'
run_mutant "M5: load eagerly in __init__" 'class ReportEngine:
    def __init__(self, loader):
        self.loader = loader
        loader.load("default.csv")
    def generate_report(self, filepath, mode):
        return mode.process_transactions(self.loader.load(filepath))'
rm -rf "$T"
